#!/usr/bin/env node
// Bundle the simulation and match-log replay for the hub server, and stamp the
// simulation fingerprint both sides compare before an online match.
//
//   node scripts/build-sim-bundle.mjs              write src/net/simVersion.ts and dist-sim/sproto-sim.js
//   node scripts/build-sim-bundle.mjs --check      fail if src/net/simVersion.ts is stale (CI)
//   node scripts/build-sim-bundle.mjs --out FILE   also copy the bundle to FILE (the hub's vendor path)
//
// The bundle targets ES2015 and defines one global, `SprotoSim`, so Nakama's
// JavaScript runtime can load it alongside the hub module.
import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync, copyFileSync } from 'node:fs';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as esbuild from 'esbuild';

const root = fileURLToPath(new URL('../', import.meta.url));
const args = process.argv.slice(2);
const result = await esbuild.build({
  entryPoints: [root + 'src/net/serverEntry.ts'], bundle: true, write: false, format: 'iife', globalName: 'SprotoSim',
  target: 'es2015', platform: 'neutral', logLevel: 'silent', legalComments: 'none',
});
const code = result.outputFiles[0].text;
const version = createHash('sha256').update(code).digest('hex').slice(0, 16);
const versionFile = root + 'src/net/simVersion.ts';
const versionSource = `// Generated by scripts/build-sim-bundle.mjs: a fingerprint of the simulation\n// bundle. Online players and the hub verifier must have the same value.\nexport const SIM_VERSION = '${version}';\n`;

if (args.includes('--check')) {
  let current = '';
  try { current = readFileSync(versionFile, 'utf8'); } catch { /* missing */ }
  if (current !== versionSource) {
    console.error('src/net/simVersion.ts is stale: run node scripts/build-sim-bundle.mjs');
    process.exit(1);
  }
  console.log(`PASS: simulation fingerprint ${version} is current.`);
  process.exit(0);
}
writeFileSync(versionFile, versionSource);
const bundle = `// Sproto Fighter simulation ${version}, generated by scripts/build-sim-bundle.mjs. Do not edit.\nvar SPROTO_SIM_VERSION = '${version}';\n${code}`;
mkdirSync(root + 'dist-sim', { recursive: true });
writeFileSync(root + 'dist-sim/sproto-sim.js', bundle);
const outIndex = args.indexOf('--out');
if (outIndex >= 0) { mkdirSync(dirname(args[outIndex + 1]), { recursive: true }); copyFileSync(root + 'dist-sim/sproto-sim.js', args[outIndex + 1]); }
console.log(`simulation ${version}: ${(bundle.length / 1024).toFixed(0)} KB`);
